package com.dgalambos.menucolorizer;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(MenuColorizerConfig.GROUP)
public interface MenuColorizerConfig extends Config
{
	String GROUP = "menucolorizer";

	@ConfigItem(
		keyName = "enableColoring",
		name = "Enable Coloring",
		description = "Enable or disable menu option coloring",
		position = 0
	)
	default boolean enableColoring()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showTagOptions",
		name = "Show Tag Options",
		description = "Show color tag options in shift-click menus",
		position = 1
	)
	default boolean showTagOptions()
	{
		return true;
	}

	@ConfigItem(
		keyName = "defaultPickerColor",
		name = "Default Picker Color",
		description = "Default color shown when opening the color picker for a new entry",
		position = 2
	)
	default Color defaultPickerColor()
	{
		return Color.GREEN;
	}

	@ConfigItem(
		keyName = "colorMappings",
		name = "Color Mappings",
		description = "Color mappings (format: targetName:optionText:#hexColor separated by semicolons)",
		position = 3
	)
	default String colorMappings()
	{
		return "";
	}
}

package com.dgalambos.menucolorizer;

import java.awt.Color;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.event.MouseListener;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.MenuOpened;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.components.colorpicker.ColorPickerManager;
import net.runelite.client.ui.components.colorpicker.RuneliteColorPicker;

@Slf4j
@PluginDescriptor(
	name = "Menu Colorizer"
)
public class MenuColorizerPlugin extends Plugin
{
	private static final Pattern COLOR_TAG = Pattern.compile("<col=[0-9a-fA-F]+>|</col>");
	private static final String SET_COLOR = "Set color";
	private static final String RESET_COLOR = "Reset color";

	@Inject
	private Client client;

	@Inject
	private ConfigManager configManager;

	@Inject
	private MenuColorizerConfig config;

	@Inject
	private ColorPickerManager colorPickerManager;

	private final Map<String, Color> colorCache = new HashMap<>();
	private final List<ColorPattern> colorPatterns = new ArrayList<>();
	private boolean showTagOptions = true;
	private boolean coloringEnabled = true;
	private volatile boolean shiftOnRightClick;

	/**
	 * Tracks shift state from the mouse event itself, not the game engine's key state.
	 * This works even when shift was pressed before the game canvas had focus
	 * (e.g. after interacting with the RuneLite config panel).
	 */
	private final MouseListener shiftTracker = new MouseAdapter()
	{
		@Override
		public void mousePressed(MouseEvent e)
		{
			if (SwingUtilities.isRightMouseButton(e))
			{
				shiftOnRightClick = (e.getModifiersEx() & MouseEvent.SHIFT_DOWN_MASK) != 0;
			}
		}
	};

	/**
	 * Maps parent menu entry identifier -> clean target text.
	 * Used to resolve which item a submenu entry belongs to.
	 * Top-level entries (e.g. "Teleport" on Construct. cape) carry the target text directly.
	 * Submenu entries (e.g. "Brimhaven") have empty target but encode their parent's
	 * identifier in the lower 16 bits: identifier = (submenuIndex << 16) | parentIdentifier.
	 */
	private final Map<Integer, String> parentTargetMap = new HashMap<>();

	@Provides
	MenuColorizerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(MenuColorizerConfig.class);
	}

	@Override
	protected void startUp()
	{
		client.getCanvas().addMouseListener(shiftTracker);
		showTagOptions = config.showTagOptions();
		coloringEnabled = config.enableColoring();
		rebuildCache();
	}

	@Override
	protected void shutDown()
	{
		client.getCanvas().removeMouseListener(shiftTracker);
		colorCache.clear();
		colorPatterns.clear();
		parentTargetMap.clear();
		showTagOptions = true;
		coloringEnabled = true;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (MenuColorizerConfig.GROUP.equals(event.getGroup()))
		{
			showTagOptions = config.showTagOptions();
			coloringEnabled = config.enableColoring();
			rebuildCache();
		}
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		MenuEntry entry = event.getMenuEntry();
		String target = stripColorTags(entry.getTarget());

		// Track targets from top-level entries so submenu entries can resolve their parent
		if (!target.isEmpty())
		{
			parentTargetMap.put(entry.getIdentifier(), target);
		}

		if (!coloringEnabled || (colorCache.isEmpty() && colorPatterns.isEmpty()))
		{
			return;
		}

		String sourceTarget = resolveSourceTarget(entry);
		String cleanOption = stripColorTags(entry.getOption());
		if (sourceTarget == null || cleanOption.isEmpty())
		{
			return;
		}

		Color color = findColor(sourceTarget, cleanOption);
		if (color != null)
		{
			String hex = String.format("%06x", color.getRGB() & 0xFFFFFF);
			entry.setOption("<col=" + hex + ">" + cleanOption + "</col>");
		}
	}

	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		if (!showTagOptions || !shiftOnRightClick)
		{
			return;
		}

		MenuEntry[] entries = event.getMenuEntries();
		for (int i = entries.length - 1; i >= 0; i--)
		{
			MenuEntry entry = entries[i];

			// Add color entries inside submenus (e.g. teleport destination lists)
			Menu subMenu = entry.getSubMenu();
			if (subMenu != null)
			{
				addColorEntriesToMenu(subMenu);
			}

			// Add color entries for the top-level entry itself
			addColorEntryFor(entry, client.getMenu(), i);
		}
	}

	private void addColorEntriesToMenu(Menu menu)
	{
		MenuEntry[] entries = menu.getMenuEntries();
		for (int i = entries.length - 1; i >= 0; i--)
		{
			addColorEntryFor(entries[i], menu, i);
		}
	}

	private void addColorEntryFor(MenuEntry entry, Menu menu, int index)
	{
		if (entry.getType() == MenuAction.RUNELITE)
		{
			return;
		}

		String sourceTarget = resolveSourceTarget(entry);
		String cleanOption = stripColorTags(entry.getOption());
		if (sourceTarget == null || cleanOption.isEmpty()
			|| "Cancel".equals(cleanOption) || "Walk here".equals(cleanOption))
		{
			return;
		}

		boolean hasExactMatch = colorCache.containsKey(cacheKey(sourceTarget, cleanOption));
		Color effective = findColor(sourceTarget, cleanOption);

		if (hasExactMatch)
		{
			menu.createMenuEntry(index + 1)
				.setOption(RESET_COLOR)
				.setTarget("<col=ffff00>" + cleanOption + "</col>")
				.setType(MenuAction.RUNELITE)
				.onClick(e -> removeColor(sourceTarget, cleanOption));
		}

		menu.createMenuEntry(index + 1)
			.setOption(SET_COLOR)
			.setTarget("<col=ffff00>" + cleanOption + "</col>")
			.setType(MenuAction.RUNELITE)
			.onClick(e -> openColorPicker(sourceTarget, cleanOption, effective));
	}

	/**
	 * Resolve the source target name for a menu entry.
	 * Top-level entries have the target directly (e.g. "Construct. cape(t)").
	 * Submenu entries derive it from their parent via the identifier encoding.
	 */
	private String resolveSourceTarget(MenuEntry entry)
	{
		String target = stripColorTags(entry.getTarget());
		if (!target.isEmpty())
		{
			return target;
		}

		int identifier = entry.getIdentifier();
		if (identifier > 0xFFFF)
		{
			int parentId = identifier & 0xFFFF;
			return parentTargetMap.get(parentId);
		}

		return null;
	}

	private void openColorPicker(String sourceTarget, String optionText, Color existing)
	{
		SwingUtilities.invokeLater(() ->
		{
			RuneliteColorPicker picker = colorPickerManager.create(
				SwingUtilities.windowForComponent(client.getCanvas()),
				existing != null ? existing : config.defaultPickerColor(),
				"Color: " + optionText + " (" + sourceTarget + ")",
				false
			);
			picker.setOnClose(c -> setColor(sourceTarget, optionText, c));
			picker.setVisible(true);
		});
	}

	private void setColor(String sourceTarget, String optionText, Color color)
	{
		String hex = String.format("#%06x", color.getRGB() & 0xFFFFFF);
		String prefix = sourceTarget + ":" + optionText + ":";
		String filtered = filterMappings(prefix);
		String newEntry = sourceTarget + ":" + optionText + ":" + hex;
		String result = filtered.isEmpty() ? newEntry : filtered + "; " + newEntry;
		configManager.setConfiguration(MenuColorizerConfig.GROUP, "colorMappings", result);
	}

	private void removeColor(String sourceTarget, String optionText)
	{
		String prefix = sourceTarget + ":" + optionText + ":";
		configManager.setConfiguration(MenuColorizerConfig.GROUP, "colorMappings", filterMappings(prefix));
	}

	private String filterMappings(String excludePrefix)
	{
		StringBuilder sb = new StringBuilder();
		String mappings = config.colorMappings();
		if (mappings != null && !mappings.isEmpty())
		{
			for (String part : mappings.split(";"))
			{
				String trimmed = part.trim();
				if (!trimmed.isEmpty() && !trimmed.startsWith(excludePrefix))
				{
					if (sb.length() > 0)
					{
						sb.append("; ");
					}
					sb.append(trimmed);
				}
			}
		}
		return sb.toString();
	}

	private void rebuildCache()
	{
		colorCache.clear();
		colorPatterns.clear();
		String mappings = config.colorMappings();
		if (mappings == null || mappings.isEmpty())
		{
			return;
		}

		for (String part : mappings.split(";"))
		{
			String trimmed = part.trim();
			if (!trimmed.isEmpty())
			{
				parseMappingEntry(trimmed);
			}
		}
	}

	private void parseMappingEntry(String entry)
	{
		// Format: sourceTarget:optionText:#hexColor
		int lastColorSep = entry.lastIndexOf(":#");
		if (lastColorSep < 0)
		{
			log.warn("Invalid color mapping (no color): {}", entry);
			return;
		}

		String hexColor = entry.substring(lastColorSep + 1);
		String rest = entry.substring(0, lastColorSep);

		int firstColon = rest.indexOf(':');
		if (firstColon < 0)
		{
			log.warn("Invalid color mapping (no separator): {}", entry);
			return;
		}

		String sourceTarget = rest.substring(0, firstColon).trim();
		String optionText = rest.substring(firstColon + 1).trim();

		try
		{
			Color color = Color.decode(hexColor);
			if (sourceTarget.contains("*") || optionText.contains("*"))
			{
				colorPatterns.add(new ColorPattern(
					globToRegex(sourceTarget),
					globToRegex(optionText),
					color
				));
			}
			else
			{
				colorCache.put(cacheKey(sourceTarget, optionText), color);
			}
		}
		catch (NumberFormatException e)
		{
			log.warn("Invalid color mapping: {}", entry, e);
		}
	}

	private static String cacheKey(String sourceTarget, String optionText)
	{
		return sourceTarget + "\0" + optionText;
	}

	private static Pattern globToRegex(String glob)
	{
		String regex = Pattern.quote(glob).replace("*", "\\E.*\\Q");
		return Pattern.compile("^" + regex + "$", Pattern.CASE_INSENSITIVE);
	}

	private Color findColor(String sourceTarget, String optionText)
	{
		Color exact = colorCache.get(cacheKey(sourceTarget, optionText));
		if (exact != null)
		{
			return exact;
		}

		for (ColorPattern cp : colorPatterns)
		{
			if (cp.sourceTargetPattern.matcher(sourceTarget).matches()
				&& cp.optionTextPattern.matcher(optionText).matches())
			{
				return cp.color;
			}
		}

		return null;
	}

	private String stripColorTags(String text)
	{
		if (text == null)
		{
			return "";
		}
		return COLOR_TAG.matcher(text).replaceAll("");
	}

	private static class ColorPattern
	{
		final Pattern sourceTargetPattern;
		final Pattern optionTextPattern;
		final Color color;

		ColorPattern(Pattern sourceTargetPattern, Pattern optionTextPattern, Color color)
		{
			this.sourceTargetPattern = sourceTargetPattern;
			this.optionTextPattern = optionTextPattern;
			this.color = color;
		}
	}
}

package com.dgalambos.menucolorizer;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class MenuColorizerPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(MenuColorizerPlugin.class);
		RuneLite.main(args);
	}
}
